# ─────────────────────────────────────────────────────────────
#  ASSET LOADERS
# ─────────────────────────────────────────────────────────────

def _decode_font(b64_data, size):
    """Decode a base64 font directly into memory — no temp files, works on all OS."""
    raw = base64.b64decode(b64_data)
    return ImageFont.truetype(io.BytesIO(raw), size)


def _remove_white_bg(img, threshold=210):
    img  = img.convert("RGBA")
    data = np.array(img)
    r, g, b, a = data[:,:,0], data[:,:,1], data[:,:,2], data[:,:,3]
    white = (r > threshold) & (g > threshold) & (b > threshold)
    near  = (r > 175)      & (g > 175)      & (b > 175)      & ~white
    data[white, 3] = 0
    data[near,  3] = 50
    return Image.fromarray(data)


def _crop_content(img):
    data  = np.array(img)
    alpha = data[:, :, 3]
    rows  = np.any(alpha > 10, axis=1)
    cols  = np.any(alpha > 10, axis=0)
    rmin, rmax = np.where(rows)[0][[0, -1]]
    cmin, cmax = np.where(cols)[0][[0, -1]]
    return img.crop((cmin, rmin, cmax + 1, rmax + 1))


def _load_logo():
    raw = base64.b64decode(_LOGO_B64)
    img = Image.open(io.BytesIO(raw))
    img = _remove_white_bg(img)
    img = _crop_content(img)
    return img


# ─────────────────────────────────────────────────────────────
#  CONSTANTS
# ─────────────────────────────────────────────────────────────
W, H      = 820, 490
PAD       = 24
INK_NAVY  = (22, 24, 82)
INK_RED   = (210, 22, 22)
MONTHS    = ["JAN","FEB","MAR","APR","MAY","JUN",
             "JUL","AUG","SEP","OCT","NOV","DEC"]


# ─────────────────────────────────────────────────────────────
#  DRAWING HELPERS
# ─────────────────────────────────────────────────────────────

def _round_rect(draw, xy, radius, color, lw):
    x0, y0, x1, y1 = xy
    r = radius
    draw.line([(x0+r,y0),(x1-r,y0)], fill=color, width=lw)
    draw.line([(x0+r,y1),(x1-r,y1)], fill=color, width=lw)
    draw.line([(x0,y0+r),(x0,y1-r)], fill=color, width=lw)
    draw.line([(x1,y0+r),(x1,y1-r)], fill=color, width=lw)
    draw.arc([x0,    y0,    x0+2*r, y0+2*r], 180, 270, fill=color, width=lw)
    draw.arc([x1-2*r,y0,    x1,     y0+2*r], 270, 360, fill=color, width=lw)
    draw.arc([x0,    y1-2*r,x0+2*r, y1    ],  90, 180, fill=color, width=lw)
    draw.arc([x1-2*r,y1-2*r,x1,     y1    ],   0,  90, fill=color, width=lw)


def _bold_text(draw, xy, text, font, fill):
    """Micro-offset renders to simulate heavy rubber-stamp ink press."""
    x, y = xy
    for dx, dy in [(0,0),(1,0),(0,1),(1,1)]:
        draw.text((x+dx, y+dy), text, font=font, fill=fill)


def _ink_noise(img, amount=0.013, seed=7):
    px  = img.load()
    rng = random.Random(seed)
    for _ in range(int(W * H * amount)):
        x = rng.randint(0, W - 1)
        y = rng.randint(0, H - 1)
        r, g, b, a = px[x, y]
        if a > 10:
            d = rng.randint(10, 40)
            px[x, y] = (max(0,r-d), max(0,g-d), max(0,b-d), a)


# ─────────────────────────────────────────────────────────────
#  STAMP RENDERER
# ─────────────────────────────────────────────────────────────

def generate_stamp(date: datetime.date) -> Image.Image:
    """Returns an RGBA PIL Image identical on every platform."""

    img  = Image.new("RGBA", (W, H), (255, 255, 255, 255))
    draw = ImageDraw.Draw(img)

    # ── border ───────────────────────────────────────────────
    _round_rect(draw, (PAD,   PAD,   W-PAD,   H-PAD  ), 12, INK_NAVY, 5)
    _round_rect(draw, (PAD+8, PAD+8, W-PAD-8, H-PAD-8),  9, INK_NAVY, 1)

    # ── logo ─────────────────────────────────────────────────
    logo   = _load_logo()
    logo_h = 112
    logo_w = int(logo.width * logo_h / logo.height)
    logo   = logo.resize((logo_w, logo_h), Image.LANCZOS)
    lx     = (W - logo_w) // 2
    ly     = PAD + 18
    img.paste(logo, (lx, ly), logo)

    # ── date ─────────────────────────────────────────────────
    day_s  = f"{date.day:02d}"
    mon_s  = MONTHS[date.month - 1]
    yr_s   = str(date.year)
    date_s = f"{day_s}   {mon_s}   {yr_s}"

    f_date = _decode_font(_FONT_MONO_B64, 56)
    bb     = draw.textbbox((0, 0), date_s, font=f_date)
    dx     = (W - (bb[2] - bb[0])) // 2
    _bold_text(draw, (dx, 172), date_s, f_date, INK_RED)

    # ── contact block ────────────────────────────────────────
    f_c = _decode_font(_FONT_SERIF_B64, 24)
    contacts = [
        "119 Harare Drive, Hatfield, Harare",
        "Cell: +263 778 924 209  /  +263 717 736 315",
        "Email: info@parkvan-calibration.co.zw",
    ]
    cy = 272
    for line in contacts:
        bb  = draw.textbbox((0, 0), line, font=f_c)
        lx2 = (W - (bb[2] - bb[0])) // 2
        _bold_text(draw, (lx2, cy), line, f_c, INK_NAVY)
        cy += 48

    # ── ink distress ─────────────────────────────────────────
    _ink_noise(img)
    img = img.filter(ImageFilter.GaussianBlur(radius=0.5))
    return img


# ─────────────────────────────────────────────────────────────
#  TKINTER GUI
# ─────────────────────────────────────────────────────────────

class StampApp(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Parkvan Calibration – Stamp Generator")
        self.resizable(False, False)
        self.configure(bg="#eef0f7")
        self._build_ui()
        self._refresh()

    def _build_ui(self):
        top = tk.Frame(self, bg="#eef0f7", pady=14)
        top.pack(fill="x", padx=20)

        tk.Label(top, text="Stamp date:", bg="#eef0f7",
                 font=("Helvetica", 11, "bold")).pack(side="left", padx=(0,8))

        self.cal = DateEntry(
            top, width=14, date_pattern="dd/mm/yyyy",
            background="#16185c", foreground="white",
            borderwidth=1, font=("Helvetica", 11),
        )
        self.cal.set_date(datetime.date.today())
        self.cal.pack(side="left")
        self.cal.bind("<<DateEntrySelected>>", lambda e: self._refresh())

        ttk.Button(top, text="↻  Refresh",  command=self._refresh).pack(side="left", padx=10)
        ttk.Button(top, text="⬇  Save PNG", command=self._save  ).pack(side="left")

        self.preview = tk.Canvas(self, width=W, height=H,
                                 bg="white", highlightthickness=1,
                                 highlightbackground="#c0c4d0")
        self.preview.pack(padx=20, pady=(0, 4))

        tk.Label(self, text="Pick any date · Save PNG exports at 300 dpi",
                 bg="#eef0f7", fg="#999", font=("Helvetica", 9)).pack(pady=(0, 12))

    def _refresh(self):
        d = self.cal.get_date()
        self._stamp_img = generate_stamp(d)
        from PIL import ImageTk
        self._tk_img = ImageTk.PhotoImage(self._stamp_img)
        self.preview.delete("all")
        self.preview.create_image(W//2, H//2, anchor="center", image=self._tk_img)

    def _save(self):
        d    = self.cal.get_date()
        name = f"parkvan_stamp_{d.strftime('%Y-%m-%d')}.png"
        path = filedialog.asksaveasfilename(
            defaultextension=".png",
            filetypes=[("PNG image","*.png"),("All files","*.*")],
            initialfile=name, title="Save stamp as …",
        )
        if not path: return
        self._stamp_img.save(path, "PNG", dpi=(300, 300))
        messagebox.showinfo("Saved", f"Stamp saved to:\n{path}", parent=self)


# ─────────────────────────────────────────────────────────────
if __name__ == "__main__":
    StampApp().mainloop()
